      "mechanism_type": "education_stem_education",
      "target_population": "Secondary students in grades 10-12, with outreach to underrepresented regions",
      "parameters": {
        "target_grade_levels": "10-12",
        "coverage_rate": 0.60,
        "dual_enrollment_courses_offered": 2
      },
      "rationale": "Intensive STEM education builds transferable academic-success skills and creates an explicit pipeline to tertiary institutions. Early exposure to university-level work and environments increases application and enrollment rates."
    },
