        "target_grade_levels": "6-8",
        "coverage_rate": 0.90,
        "dialogic_sessions_per_week": 2
      },
      "rationale": "Foundational literacy is a key predictor of school persistence. Dialogic reading improves story comprehension and higher-order language skills, reducing early secondary dropout and building the discursive competencies required for advanced study."
    }
  ],
